static int whirl_selftest(whirl_derive_fn derive)
{
    uint8_t salt[64], passwords[8 * 64], out[8 * 64];
    for (int q = 0; q < 64; q++) salt[q] = (uint8_t)q;
    for (int k = 0; k < 4; k++)
    {
        int len = WHIRL_TEST_LENGTHS[k];
        for (int l = 0; l < 8; l++)
            for (int q = 0; q < len; q++) passwords[l * len + q] = (uint8_t)(l * 17 + q * 7 + 33);
        derive(salt, passwords, len, 8, out);
        if (memcmp(out, WHIRL_TEST_ANSWERS[k], sizeof out) != 0) return 0;
    }
    return 1;
}
